module DVFS_Controller_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg enable;
    reg [1:0] performance_level;
    wire [2:0] frequency;
    wire [1:0] voltage;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    DVFS_Controller dut (
        .clk(clk),
        .enable(enable),
        .performance_level(performance_level),
        .frequency(frequency),
        .voltage(voltage)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            enable = 0;
            performance_level = 2'b00;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Lowest Performance Level (00)", test_num);
            reset_dut();
            enable = 1;
            performance_level = 2'b00;
            @(posedge clk);
            #2;

            #1;


            check_outputs(3'b001, 2'b00);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Medium Performance Level (01)", test_num);
            reset_dut();
            enable = 1;
            performance_level = 2'b01;
            @(posedge clk);
            #2;

