module VirtualMemory(
    input clk,
    input rst,
    input [15:0] virtual_address,
    output reg [15:0] physical_address
);
    reg [15:0] page_table [0:15]; // A simple page table with 16 entries
    wire [3:0] page_number; // Extract the page number
    wire [3:0] offset; // Extract the offset

    assign page_number = virtual_address[15:12]; // Get the page number from the address
    assign offset = virtual_address[11:0]; // Get the offset from the address

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            physical_address <= 16'b0; // Reset the physical address
        end else begin
            physical_address <= {page_table[page_number], offset}; // Translate virtual to physical address
        end
    end

    initial begin
        // Initialize the page table with some values (for simulation purpose)
        page_table[0] = 16'h0000;
        page_table[1] = 16'h1000;
        page_table[2] = 16'h2000;
        page_table[3] = 16'h3000;
        page_table[4] = 16'h4000;
        page_table[5] = 16'h5000;
        page_table[6] = 16'h6000;
        page_table[7] = 16'h7000;
        page_table[8] = 16'h8000;
        page_table[9] = 16'h9000;
        page_table[10] = 16'hA000;
        page_table[11] = 16'hB000;
        page_table[12] = 16'hC000;
        page_table[13] = 16'hD000;
        page_table[14] = 16'hE000;
        page_table[15] = 16'hF000;
    end
endmodule

