module serializer (
    input clk,
    input reset,
    input start,
    input [7:0] parallel_in,
    output reg serial_out,
    output reg valid
);
    reg [2:0] count; // 3 bits to count from 0 to 7
    reg [7:0] data;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            serial_out <= 0;
            valid <= 0;
            data <= 0;
        end else if (start) begin
            data <= parallel_in;
            count <= 0;
            valid <= 1; // Start outputting valid data
        end else if (valid) begin
            if (count < 8) begin
                serial_out <= data[7]; // Output the MSB first
                data <= {data[6:0], 1'b0}; // Shift left
                count <= count + 1;
            end else begin
                valid <= 0; // Stop when done
            end
        end
    end
endmodule

