module rng(clk, reset, seed, random_out);  
    input clk;  
    input reset;  
    input [15:0] seed;  
    output reg [15:0] random_out;  

    reg [15:0] lfsr;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            lfsr <= seed;  
        end else begin  
            lfsr <= {lfsr[14:0], lfsr[15] ^ lfsr[13] ^ lfsr[11] ^ lfsr[10]};  
        end  
    end  

    always @(posedge clk) begin  
        random_out <= lfsr;  
    end  
endmodule

