module bfs #(parameter N = 5) (  
    input clk,  
    input [N*N-1:0] adj_matrix,  
    input [2:0] start_node,  
    output reg [N-1:0] visited  
);  
    reg [N-1:0] queue [0:N-1];  
    reg [3:0] front, rear;  
    reg [N-1:0] current_level, next_level;  
    integer i;  

    initial begin  
        visited = 0;  
        front = 0;  
        rear = 0;  
        current_level = 1 << start_node;  
        queue[rear] = start_node;  
        rear = rear + 1;  
    end  

    always @(posedge clk) begin  
        if (front < rear) begin  
            // Dequeue  
            current_level = queue[front];  
            front = front + 1;  
            visited[current_level] = 1;  
            // Enqueue adjacent nodes  
            for (i = 0; i < N; i = i + 1) begin  
                if (adj_matrix[current_level * N + i] && !visited[i]) begin  
                    queue[rear] = i;  
                    rear = rear + 1;  
                end  
            end  
        end  
    end  
endmodule

module temperature_shutdown (  
    input wire clk,  
    input wire rst,  
    input wire enable,  
    input wire [7:0] temperature,  
    output reg shutdown  
);  

    reg [1:0] state;  
    parameter IDLE = 2'b00, MONITOR = 2'b01, SHUTDOWN = 2'b10;  
    reg [1:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            shutdown <= 0;  
            count <= 0;  
        end else if (enable) begin  
            case (state)  
                IDLE: begin  
                    shutdown <= 0;  
                    if (temperature > 8'd75) begin  
                        state <= MONITOR;  
                        count <= count + 1;  
                    end  
                end  
                MONITOR: begin  
                    if (temperature > 8'd75) begin  
                        count <= count + 1;  
                        if (count == 2'b11)  
                            state <= SHUTDOWN;  
                    end else begin  
                        state <= IDLE;  
                        count <= 0;  
                    end  
                end  
                SHUTDOWN: begin  
                    shutdown <= 1;  
                    if (temperature <= 8'd75) begin  
                        state <= IDLE;  
                        count <= 0;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

