module neural_net_layer (  
    input clk,  
    input rst,  
    input enable,  
    input [3:0] inputs,  
    output reg [3:0] outputs  
);  
    reg [3:0] weights;  
    reg [3:0] bias;  
    reg [3:0] deltas;  
    parameter learning_rate = 4'b0001; // Fixed learning rate  

    // Initialize weights and bias  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            weights <= 4'b0001;  
            bias <= 4'b0000;  
        end else if (enable) begin  
            // Forward pass  
            outputs <= (inputs * weights) + bias;  
            // Backpropagation step  
            deltas <= (outputs - inputs) >> 1; // Example delta calculation  
            weights <= weights - (deltas * learning_rate);  
            bias <= bias - (deltas * learning_rate);  
        end  
    end  
endmodule

