module HMAC (
    input clk,
    input reset,
    input [7:0] key,
    input [7:0] msg,
    output reg [7:0] mac
);
    reg [7:0] hash1;
    reg [7:0] hash2;

    // Simple hash function for demonstration purposes
    function [7:0] simple_hash;
        input [15:0] data;
        begin
            simple_hash = data[7:0] ^ data[15:8]; // Example: XOR of the two bytes
        end
    endfunction

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            mac <= 8'b0;
            hash1 <= 8'b0;
            hash2 <= 8'b0;
        end else begin
            hash1 <= simple_hash({key, msg}); // Hashing key and msg
            hash2 <= simple_hash({key, hash1}); // Hashing again with the key
            mac <= hash2; // Output the final MAC
