module rsa_encrypt (
    input clk,
    input rst,
    input [7:0] base,
    input [7:0] exponent,
    input [7:0] modulus,
    output reg [7:0] result,
    output reg done
);
    reg [7:0] temp_base;
    reg [7:0] temp_result;
    reg [7:0] temp_exponent;
    reg [3:0] bit_count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            result <= 0;
            done <= 0;
            temp_base <= 0;
            temp_result <= 1;
            temp_exponent <= 0;
            bit_count <= 0;
        end else if (bit_count == 0) begin
            temp_base <= base % modulus;
            temp_exponent <= exponent;
            bit_count <= 8; // We will process all 8 bits of exponent
        end else if (bit_count > 0) begin
            bit_count <= bit_count - 1;
            if (temp_exponent[0] == 1) begin
                temp_result <= (temp_result * temp_base) % modulus;
            end
            temp_base <= (temp_base * temp_base) % modulus;
            temp_exponent <= temp_exponent >> 1;

            if (bit_count == 1) begin
                result <= temp_result;
                done <= 1;
            end else begin
                done <= 0;
            end
        end
    end
endmodule

