module PID_Controller (
    input clk,
    input reset,
    input [15:0] setpoint,
    input [15:0] measured_value,
    input [15:0] Kp,  // Proportional gain
    input [15:0] Ki,  // Integral gain
    input [15:0] Kd,  // Derivative gain
    output reg [15:0] control_signal
);

reg [15:0] error;
reg [15:0] previous_error;
reg [31:0] integral;
reg [15:0] derivative;

// Update control signal on clock edge
always @(posedge clk or posedge reset) begin
    if (reset) begin
        control_signal <= 16'b0;
        previous_error <= 16'b0;
        integral <= 32'b0;
    end else begin
        error <= setpoint - measured_value;

        integral <= integral + error; // accumulate error for integral term
        derivative <= error - previous_error; // calculate derivative term

        // PID control signal calculation
        control_signal <= (Kp * error) + (Ki * integral[15:0]) + (Kd * derivative);

        previous_error <= error; // update previous error
    end
end

endmodule

