module freq_divider (
    input clk,
    input rst,
    output reg [3:0] out
);
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 4'b0000;
            out <= 4'b0000;
        end else begin
            if (count == 4'b1111) begin
                count <= 4'b0000;
                out <= ~out; // Toggle the output
            end else begin
                count <= count + 1;
            end
        end
    end
endmodule

