module uart_controller(  
    input wire clk,  
    input wire start,  
    input wire stop,  
    input wire [7:0] data_in,  
    output reg tx  
);  
    reg [3:0] bit_counter;  
    reg [7:0] data_reg;  
    reg transmitting;  

    always @(posedge clk) begin  
        if (start) begin  
            data_reg <= data_in;  
            bit_counter <= 0;  
            transmitting <= 1;  
        end  
        else if (transmitting) begin  
            if (stop) begin  
                transmitting <= 0;  
                tx <= 1;  
            end  
            else if (bit_counter < 8) begin  
                tx <= data_reg[bit_counter];  
                bit_counter <= bit_counter + 1;  
            end  
            else begin  
                transmitting <= 0;  
                tx <= 1;  
            end  
        end  
        else begin  
            tx <= 1; // Idle state  
        end  
    end  
endmodule

