module vco (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] control_voltage,  
    output reg vco_out  
);  

    reg [15:0] counter;  
    reg [15:0] frequency;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            vco_out <= 0;  
        end else begin  
            frequency <= (control_voltage * 1000) + 5000; // Frequency range adjustment  
            if (counter >= (50000000 / frequency)) begin // Assuming clk is 50MHz  
                vco_out <= ~vco_out;  
                counter <= 0;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  
endmodule

