module WatchdogTimer (  
    input clk,  
    input reset,  
    input signal_in,  
    output reg signal_out  
);  
    parameter TIMEOUT = 10;  // timeout period in clock cycles  
    reg [3:0] counter;  
    reg last_signal;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            signal_out <= 1;  
            last_signal <= 0;  
        end else begin  
            if (signal_in != last_signal) begin  
                counter <= 0;  // reset counter on signal toggle  
                last_signal <= signal_in;  
                signal_out <= 1;  
            end else begin  
                if (counter < TIMEOUT) begin  
                    counter <= counter + 1;  
                end else begin  
                    signal_out <= 0;  // reset output if timeout reached  
                end  
            end  
        end  
    end  
endmodule

