module watchdog_timer (  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    output reg timeout  
);  
    parameter MAX_COUNT = 8'd100;  
    reg [7:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 8'd0;  
            timeout <= 1'b0;  
        end  
        else if (enable) begin  
            if (count < MAX_COUNT) begin  
                count <= count + 1;  
                timeout <= 1'b0;  
            end  
            else begin  
                timeout <= 1'b1;  
            end  
        end  
    end  
endmodule

