module uart_transmitter(
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg done
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // Assuming a 50MHz clock
    localparam BIT_TIME = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_counter;
    reg [12:0] clk_divider;
    reg [7:0] data_reg;
    reg transmitting;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1; // Idle state is high
            done <= 0;
            bit_counter <= 0;
            clk_divider <= 0;
            transmitting <= 0;
        end else begin
            if (start && !transmitting) begin
                data_reg <= data_in;
                transmitting <= 1;
                bit_counter <= 0;
                clk_divider <= 0;
                tx <= 0; // Start bit
            end

            if (transmitting) begin
                clk_divider <= clk_divider + 1;
                if (clk_divider == BIT_TIME - 1) begin
                    clk_divider <= 0;
                    if (bit_counter < 8) begin
                        tx <= data_reg[bit_counter]; // Send data bits
                        bit_counter <= bit_counter + 1;
                    end else if (bit_counter == 8) begin
                        tx <= 1; // Stop bit
                        bit_counter <= bit_counter + 1;
                    end else begin
                        done <= 1; // Transmission finished
                        transmitting <= 0; // Reset to idle state
                        tx <= 1; // Idle state
                    end
                end
            end
        end
    end
endmodule

