module deserializer (
    input wire clk,
    input wire serial_in,
    output reg [31:0] parallel_out
);
    reg [4:0] bit_count; // 5 bits for counting up to 32

    always @(negedge clk) begin
        if (bit_count < 32) begin
            parallel_out[bit_count] <= serial_in;
            bit_count <= bit_count + 1;
        end
        if (bit_count == 31) begin
            bit_count <= 0; // Reset counter after 32 bits
        end
    end

    initial begin
        bit_count = 0;
        parallel_out = 32'b0;
    end
endmodule

