module dma_controller(  
    input clk,  
    input reset,  
    input start,  
    input [2:0] channel,  
    input [7:0] address,  
    input [7:0] data_in,  
    output reg done  
);  
    reg [2:0] current_channel;  
    reg [7:0] mem_address;  
    reg [7:0] data;  
    reg transferring;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            done <= 0;  
            transferring <= 0;  
        end else if (start && !transferring) begin  
            transferring <= 1;  
            current_channel <= channel;  
            mem_address <= address;  
            data <= data_in;  
        end else if (transferring) begin  
            // Simulating data transfer  
            if (current_channel != 3'b000) begin  
                transferring <= 0;  
                done <= 1;  
            end  
        end  
    end  
endmodule

