module sha256_hash (
    input clk,
    input rst,
    input [31:0] data_in,
    input valid,
    output reg [255:0] hash_out
);
    reg [255:0] hash;
    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            hash <= 256'h0;
        end else if (valid) begin
            // Simple hash function: XOR data with hash
            hash = hash ^ {data_in, data_in, data_in, data_in}; // Example operation
        end
    end

    always @(posedge clk) begin
        hash_out <= hash;
    end
endmodule

module mux4to1 (  
    input [3:0] I,  // 4 input lines  
    input [1:0] S,  // 2 selection lines  
    output Y        // output line  
);  
    assign Y = (S == 2'b00) ? I[0] :  
               (S == 2'b01) ? I[1] :  
               (S == 2'b10) ? I[2] :  
               (S == 2'b11) ? I[3] : 1'bx;  
endmodule

