module dma_controller (
    input wire clk,
    input wire rst,
    input wire req0,
    input wire req1,
    output reg grant0,
    output reg grant1,
    output reg done
);
    reg state; // 0: Channel 0, 1: Channel 1
    reg in_progress;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            grant0 <= 0;
            grant1 <= 0;
            done <= 0;
            state <= 0;
            in_progress <= 0;
        end else begin
            if (in_progress) begin
                done <= 1;
                in_progress <= 0; // Transfer done
                grant0 <= 0;
                grant1 <= 0;
            end else begin
                if (req0 && !req1) begin // Only req0 active
                    grant0 <= 1;
                    grant1 <= 0;
                    in_progress <= 1;
                end else if (req1 && !req0) begin // Only req1 active
                    grant0 <= 0;
                    grant1 <= 1;
                    in_progress <= 1;
                end else if (req0 && req1) begin // Both requests
                    if (state == 0) begin
                        grant0 <= 1;
                        grant1 <= 0;
                        state <= 1; // Switch to channel 1 next
                    end else begin
                        grant0 <= 0;
                        grant1 <= 1;
                        state <= 0; // Switch to channel 0 next
                    end
                    in_progress <= 1;
                end else begin
                    grant0 <= 0;
                    grant1 <= 0;
                    done <= 0;
                end
            end
        end
    end
endmodule

module morphological_dilation (
    input [8:0] img,  // 3x3 binary image represented as a single 9-bit input
    output reg out     // Output of the dilation operation
);
    always @(*) begin
        out = (img[0] | img[1] | img[2] | img[3] | img[4] | img[5] | img[6] | img[7] | img[8]);
    end
endmodule

