module uart_tx #(
    parameter BAUD_RATE = 9600,
    parameter CLOCK_FREQ = 50000000
) (
    input wire clk,
    input wire rst,
    input wire tx_en,
    input wire [7:0] data,
    output reg tx
);
    reg [3:0] bit_count;
    reg [9:0] shift_reg;
    reg baud_clk;

    // Baud clock generation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            baud_clk <= 0;
        end else begin
            // Simple baud clock generator
            // For simplicity, we consider a fixed divisor
            baud_clk <= ~baud_clk;
        end
    end

    // Transmit logic
    always @(posedge baud_clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // Idle state
            bit_count <= 0;
            shift_reg <= 0;
        end else if (tx_en) begin
            if (bit_count < 10) begin // 8 data bits + start + stop bit
                tx <= shift_reg[0];
                shift_reg <= {1'b1, shift_reg[9:1]}; // Shift out
                bit_count <= bit_count + 1;
            end else begin
                tx <= 1; // Idle state after transmission
                bit_count <= 0;
                shift_reg <= 0; // Reset shift register
            end
        end else begin
            tx <= 1; // Idle state
            bit_count <= 0;
            shift_reg <= {1'b1, data, 1'b0}; // Load data with start and stop bits
        end
    end
endmodule

