module interrupt_controller (
    input wire clk,
    input wire reset,
    input wire [3:0] irq,          // Interrupt requests
    input wire [3:0] irq_enable,   // Interrupt enable signals
    output reg int_out,            // Interrupt output signal
    output reg [3:0] irq_ack       // Interrupt acknowledgment output
);
    reg [3:0] irq_status;          // Current status of interrupts

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            int_out <= 0;
            irq_status <= 0;
            irq_ack <= 0;
        end else begin
            // Update the interrupt status based on enabled interrupts
            irq_status <= (irq & irq_enable);
            // Check for any active interrupts
            if (|irq_status) begin
                int_out <= 1;            // Set interrupt output high
                irq_ack <= irq_status;   // Acknowledge active interrupts
                // Clear the acknowledged interrupts
                irq_status <= irq_status & ~irq_ack;
            end else begin
                int_out <= 0;            // No active interrupts
                irq_ack <= 0;            // Clear acknowledgment
            end
        end
    end
endmodule

module pipeline_processor(clk, reset, instr, result);  
  input clk;  
  input reset;  
  input [31:0] instr;  
  output reg [31:0] result;  

  reg [31:0] reg_file [0:3]; // 4 general purpose registers  
  reg [31:0] pc; // program counter  
  reg [31:0] if_id_instr;  
  reg [31:0] id_ex_a, id_ex_b;  
  reg [31:0] ex_mem_result;  
  reg [1:0] ex_mem_op; // operation type: 00-add, 01-subtract  

  // IF stage  
  always @(posedge clk or posedge reset) begin  
    if (reset) begin  
      pc <= 0;  
    end else begin  
      if_id_instr <= instr;  
      pc <= pc + 4;  
    end  
  end  

  // ID stage  
  always @(posedge clk) begin  
    id_ex_a <= reg_file[if_id_instr[25:21]]; // rs  
    id_ex_b <= reg_file[if_id_instr[20:16]]; // rt  
    ex_mem_op <= if_id_instr[31:30]; // operation code  
  end  

  // EX stage  
  always @(posedge clk) begin  
    case (ex_mem_op)  
      2'b00: ex_mem_result <= id_ex_a + id_ex_b; // ADD  
      2'b01: ex_mem_result <= id_ex_a - id_ex_b; // SUB  
      default: ex_mem_result <= 0;  
    endcase  
  end  

  // MEM stage (not used in this simple example)  
  always @(posedge clk) begin  
    result <= ex_mem_result; // write back result to output  
  end  
endmodule

