    input [15:0] data_in,
    input compute,
    output reg [15:0] checksum
);
    reg [15:0] sum;

    always @(*) begin
        if (compute) begin
            sum = data_in; // Start with the first word
            checksum = ~sum; // One's complement for initial value
        end else begin
            // Keep the previous checksum
            checksum = checksum;
        end
    end
